1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Calculator</title>
7	<style>
8	  * { box-sizing: border-box; }
9	  body {
10	    margin: 0;
11	    min-height: 100vh;
12	    display: flex;
13	    align-items: center;
14	    justify-content: center;
15	    background: #eef0f3;
16	    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
17	  }
18	  .calc {
19	    width: 300px;
20	    padding: 16px;
21	    background: #1f2329;
22	    border-radius: 16px;
23	    box-shadow: 0 10px 30px rgba(0, 0, 0, 0.25);
24	  }
25	  .display {
26	    height: 72px;
27	    margin-bottom: 12px;
28	    padding: 0 12px;
29	    display: flex;
30	    align-items: center;
31	    justify-content: flex-end;
32	    background: #111418;
33	    color: #fff;
34	    font-size: 40px;
35	    border-radius: 10px;
36	    overflow: hidden;
37	    white-space: nowrap;
38	  }
39	  .screen { position: relative; }
40	  .mem-indicator {
41	    position: absolute;
42	    top: 6px;
43	    left: 10px;
44	    font-size: 12px;
45	    color: #9aa0a8;
46	    opacity: 0.25;
47	  }
48	  .mem-indicator[data-active="true"] { color: #f0a030; opacity: 1; }
49	  button.mem { background: #2c3138; font-size: 18px; }
50	  .keys {
51	    display: grid;
52	    grid-template-columns: repeat(4, 1fr);
53	    gap: 8px;
54	  }
55	  button {
56	    height: 56px;
57	    border: 0;
58	    border-radius: 10px;
59	    background: #3a3f47;
60	    color: #fff;
61	    font-size: 22px;
62	    cursor: pointer;
63	  }
64	  button:active { filter: brightness(1.3); }
65	  button.op { background: #f0a030; }
66	  button.clear { background: #a5a5a5; color: #111; }
67	  button.equals { background: #3c8cf0; }
68	  button.wide { grid-column: span 2; }
69	  .tape {
70	    margin-top: 12px;
71	    padding: 8px 12px;
72	    background: #111418;
73	    border-radius: 10px;
74	    color: #fff;
75	  }
76	  .tape-head {
77	    display: flex;
78	    align-items: center;
79	    justify-content: space-between;
80	    font-size: 13px;
81	    color: #9aa0a8;
82	  }
83	  .tape-head button {
84	    height: auto;
85	    padding: 4px 10px;
86	    font-size: 13px;
87	    background: #3a3f47;
88	  }
89	  .tape-rows { max-height: 160px; overflow-y: auto; }
90	  .tape-row {
91	    padding: 6px 0;
92	    border-top: 1px solid #2a2f36;
93	    text-align: right;
94	    overflow-wrap: anywhere;
95	  }
96	  .tape-row:first-child { border-top: 0; }
97	  .tape-expr { font-size: 13px; color: #9aa0a8; }
98	  .tape-result { font-size: 18px; }
99	</style>
100	</head>
101	<body>
102	<div class="calc">
103	  <div class="screen">
104	    <div class="display" data-testid="calc-display" data-value="0" data-error="false" aria-live="polite">0</div>
105	    <div class="mem-indicator" data-testid="mem-indicator" data-active="false" aria-label="memory">M</div>
106	  </div>
107	  <div class="keys">
108	    <button class="mem" data-testid="key-mc" aria-label="memory clear">MC</button>
109	    <button class="mem" data-testid="key-mr" aria-label="memory recall">MR</button>
110	    <button class="mem wide" data-testid="key-mplus" aria-label="memory add">M+</button>
111	
112	    <button class="clear wide" data-testid="key-lparen" aria-label="open group">(</button>
113	    <button class="clear wide" data-testid="key-rparen" aria-label="close group">)</button>
114	
115	    <button class="clear wide" data-testid="key-clear">AC</button>
116	    <button class="clear" data-testid="key-sign" aria-label="change sign">±</button>
117	    <button class="op" data-testid="key-div" aria-label="divide">÷</button>
118	
119	    <button data-testid="key-7">7</button>
120	    <button data-testid="key-8">8</button>
121	    <button data-testid="key-9">9</button>
122	    <button class="op" data-testid="key-mul" aria-label="multiply">×</button>
123	
124	    <button data-testid="key-4">4</button>
125	    <button data-testid="key-5">5</button>
126	    <button data-testid="key-6">6</button>
127	    <button class="op" data-testid="key-sub" aria-label="subtract">−</button>
128	
129	    <button data-testid="key-1">1</button>
130	    <button data-testid="key-2">2</button>
131	    <button data-testid="key-3">3</button>
132	    <button class="op" data-testid="key-add" aria-label="add">+</button>
133	
134	    <button class="wide" data-testid="key-0">0</button>
135	    <button data-testid="key-dot" aria-label="decimal point">.</button>
136	    <button class="equals" data-testid="key-equals" aria-label="equals">=</button>
137	  </div>
138	  <div class="tape">
139	    <div class="tape-head">
140	      <span>History</span>
141	      <button data-testid="tape-clear">Clear</button>
142	    </div>
143	    <div class="tape-rows" data-testid="calc-tape" aria-label="past calculations"></div>
144	  </div>
145	</div>
146	<script>
147	(function () {
148	  var display = document.querySelector('[data-testid="calc-display"]');
149	  var tape = document.querySelector('[data-testid="calc-tape"]');
150	  var memIndicator = document.querySelector('[data-testid="mem-indicator"]');
151	
152	  // [REQ-009] Memory lives outside state, so AC keeps it. It holds the full,
153	  // unrounded value; rounding stays presentation only.
154	  var memory = 0;
155	
156	  // entry: string being typed, or null when no entry is in progress.
157	  // value: the number currently shown when not typing (result or stored operand).
158	  // derived: true when entry came from ± on a computed number rather than typing;
159	  // it is shown formatted, and the next digit starts a new entry.
160	
161	  // groups: stack of the outer { stored, op, expr } saved by each open "(".
162	  // expr: tokens of the expression written so far at the current group level.
163	  // entryExpr: how the entry reads in the expression when it is a closed group.
164	  var state;
165	
166	  var opSymbols = { add: '+', sub: '−', mul: '×', div: '÷' };
167	
168	  // [REQ-001] [REQ-004] [REQ-005] [REQ-007]
169	  function reset() {
170	    state = { entry: null, value: 0, stored: null, op: null, error: false, derived: false, groups: [],
171	      expr: [], entryExpr: null };
172	  }
173	
174	  // [REQ-007]
175	  // How the current operand reads in the tape expression.
176	  function operandText() {
177	    if (state.entry === null) return formatNumber(state.value);
178	    if (state.entryExpr !== null) return state.entryExpr;
179	    if (state.derived) return formatNumber(Number(state.entry));
180	    return state.entry.replace(/\.$/, '');
181	  }
182	
183	  // [REQ-007]
184	  // Newest row first. The tape is not part of state, so AC keeps it.
185	  function addTapeRow(expr, result) {
186	    var row = document.createElement('div');
187	    row.className = 'tape-row';
188	    row.setAttribute('data-testid', 'tape-row');
189	    var e = document.createElement('div');
190	    e.className = 'tape-expr';
191	    e.setAttribute('data-testid', 'tape-expr');
192	    e.textContent = expr;
193	    var r = document.createElement('div');
194	    r.className = 'tape-result';
195	    r.setAttribute('data-testid', 'tape-result');
196	    r.setAttribute('data-value', String(result));
197	    r.textContent = formatNumber(result);
198	    row.appendChild(e);
199	    row.appendChild(r);
200	    tape.insertBefore(row, tape.firstChild);
201	  }
202	
203	  // [REQ-001]
204	  function compute(a, op, b) {
205	    var r;
206	    if (op === 'add') r = a + b;
207	    else if (op === 'sub') r = a - b;
208	    else if (op === 'mul') r = a * b;
209	    else if (op === 'div') r = a / b;
210	    // [REQ-003] Division by zero (or any non-finite result) becomes the error state.
211	    // The result is never rounded here: rounding is presentation only.
212	    if (!isFinite(r)) return NaN;
213	    return r;
214	  }
215	
216	  // [REQ-003]
217	  // Presentation only: at most 10 significant digits, no trailing zeros, no
218	  // thousands separators, exponential only for |n| >= 1e10 or |n| < 1e-9.
219	  function formatNumber(n) {
220	    if (n === 0) return '0';
221	    var r = Number(n.toPrecision(10));
222	    var abs = Math.abs(r);
223	    if (abs >= 1e10 || abs < 1e-9) {
224	      return r.toExponential(9).replace(/\.?0+e/, 'e');
225	    }
226	    var exp = parseInt(r.toExponential().split('e')[1], 10);
227	    var s = r.toFixed(Math.max(0, 9 - exp));
228	    return s.indexOf('.') === -1 ? s : s.replace(/\.?0+$/, '');
229	  }
230	
231	  // [REQ-001] [REQ-003] [REQ-009]
232	  function render() {
233	    memIndicator.setAttribute('data-active', memory !== 0 ? 'true' : 'false');
234	    display.setAttribute('data-error', state.error ? 'true' : 'false');
235	    if (state.error) {
236	      display.textContent = 'Error';
237	      display.setAttribute('data-value', String(NaN));
238	      return;
239	    }
240	    if (state.entry !== null) {
241	      display.textContent = state.derived ? formatNumber(Number(state.entry)) : state.entry;
242	      display.setAttribute('data-value', String(Number(state.entry)));
243	    } else {
244	      display.textContent = formatNumber(state.value);
245	      display.setAttribute('data-value', String(state.value));
246	    }
247	  }
248	
249	  // [REQ-001] [REQ-007]
250	  function inputDigit(d) {
251	    if (state.derived) { state.entry = null; state.derived = false; state.entryExpr = null; }
252	    if (state.entry === null || state.entry === '0') state.entry = d;
253	    else state.entry += d;
254	  }
255	
256	  // [REQ-001] [REQ-007]
257	  function inputDot() {
258	    if (state.derived) { state.entry = null; state.derived = false; state.entryExpr = null; }
259	    if (state.entry === null) state.entry = '0.';
260	    else if (state.entry.indexOf('.') === -1) state.entry += '.';
261	  }
262	
263	  // [REQ-004] [REQ-006] [REQ-007]
264	  // ± acts on the current entry. With no entry in progress, the number on
265	  // the display becomes the entry, so it can still feed the pending operation.
266	  function inputSign() {
267	    if (state.entry === null) { state.entry = String(state.value); state.derived = true; }
268	    state.entry = state.entry.charAt(0) === '-' ? state.entry.slice(1) : '-' + state.entry;
269	    if (state.entryExpr !== null) {
270	      state.entryExpr = state.entryExpr.charAt(0) === '-' ? state.entryExpr.slice(1) : '-' + state.entryExpr;
271	    }
272	  }
273	
274	  // [REQ-001] [REQ-002] [REQ-007]
275	  // Immediate execution: an operator key first finishes the waiting operation,
276	  // strictly left to right, with no precedence, so the display always shows a
277	  // real running result. 2 + 3 × 4 = 20.
278	  function inputOperator(op) {
279	    if (state.error) return;
280	    if (state.entry === null && state.expr.length > 0) {
281	      // A second operator in a row replaces the first.
282	      state.expr[state.expr.length - 1] = opSymbols[op];
283	    } else {
284	      state.expr.push(operandText(), opSymbols[op]);
285	    }
286	    if (state.entry !== null) {
287	      var n = Number(state.entry);
288	      state.entry = null;
289	      state.derived = false;
290	      state.entryExpr = null;
291	      if (state.op !== null && state.stored !== null) {
292	        state.value = compute(state.stored, state.op, n);
293	        if (isNaN(state.value)) { state.error = true; return; }
294	      } else {
295	        state.value = n;
296	      }
297	    }
298	    state.stored = state.value;
299	    state.op = op;
300	  }
301	
302	  // [REQ-005] [REQ-007]
303	  // "(" starts a group only where a new number could start. It saves the waiting
304	  // operation and begins a fresh calculation inside the group.
305	  function inputOpenGroup() {
306	    if (state.entry !== null) return;
307	    state.groups.push({ stored: state.stored, op: state.op, expr: state.expr });
308	    state.stored = null;
309	    state.op = null;
310	    state.expr = [];
311	  }
312	
313	  // [REQ-005] [REQ-007]
314	  // ")" finishes the calculation inside the group, left to right, and hands its
315	  // result back as the entry for the saved outer operation.
316	  function inputCloseGroup() {
317	    if (state.groups.length === 0 || state.entry === null) return;
318	    var n = Number(state.entry);
319	    if (state.op !== null && state.stored !== null) {
320	      n = compute(state.stored, state.op, n);
321	      if (isNaN(n)) { state.error = true; return; }
322	    }
323	    var inner = state.expr.concat(operandText()).join(' ');
324	    var outer = state.groups.pop();
325	    state.stored = outer.stored;
326	    state.op = outer.op;
327	    state.expr = outer.expr;
328	    state.value = n;
329	    state.entry = String(n);
330	    state.derived = true;
331	    state.entryExpr = '(' + inner + ')';
332	  }
333	
334	  // [REQ-009]
335	  // M+ adds the unrounded displayed number. A typed entry is finished, so the
336	  // next digit starts a new number, but it still feeds the pending operation.
337	  function inputMemoryAdd() {
338	    var n = state.entry !== null ? Number(state.entry) : state.value;
339	    var sum = compute(memory, 'add', n);
340	    if (isNaN(sum)) { state.error = true; return; }
341	    memory = sum;
342	    if (state.entry !== null) state.derived = true;
343	  }
344	
345	  // [REQ-009]
346	  // MR puts the memory value in as the current entry, replacing any entry.
347	  function inputMemoryRecall() {
348	    state.entry = String(memory);
349	    state.derived = true;
350	    state.entryExpr = null;
351	  }
352	
353	  // [REQ-001] [REQ-005] [REQ-007]
354	  function inputEquals() {
355	    // Groups still open are closed first.
356	    while (!state.error && state.groups.length > 0 && state.entry !== null) inputCloseGroup();
357	    if (state.error || state.op === null || state.entry === null) return;
358	    var result = compute(state.stored, state.op, Number(state.entry));
359	    var expr = state.expr.concat(operandText()).join(' ');
360	    state.entry = null;
361	    state.derived = false;
362	    state.entryExpr = null;
363	    state.expr = [];
364	    state.op = null;
365	    state.stored = null;
366	    if (isNaN(result)) { state.error = true; return; }
367	    state.value = result;
368	    addTapeRow(expr, result);
369	  }
370	
371	  // [REQ-001] [REQ-003] [REQ-004] [REQ-005] [REQ-006] [REQ-009] The % key was removed.
372	  function press(key) {
373	    // In the error state every key except clear is ignored.
374	    if (state.error && key !== 'clear') return;
375	    if (/^[0-9]$/.test(key)) inputDigit(key);
376	    else if (key === 'dot') inputDot();
377	    else if (key === 'sign') inputSign();
378	    else if (key === 'add' || key === 'sub' || key === 'mul' || key === 'div') inputOperator(key);
379	    else if (key === 'lparen') inputOpenGroup();
380	    else if (key === 'rparen') inputCloseGroup();
381	    else if (key === 'equals') inputEquals();
382	    else if (key === 'clear') reset();
383	    else if (key === 'mplus') inputMemoryAdd();
384	    else if (key === 'mr') inputMemoryRecall();
385	    else if (key === 'mc') memory = 0;
386	    render();
387	  }
388	
389	  document.querySelector('.keys').addEventListener('click', function (e) {
390	    var btn = e.target.closest('button[data-testid^="key-"]');
391	    if (btn) press(btn.getAttribute('data-testid').slice(4));
392	  });
393	
394	  // [REQ-007] Empties the tape only; the display and calculation are untouched.
395	  document.querySelector('[data-testid="tape-clear"]').addEventListener('click', function () {
396	    tape.textContent = '';
397	  });
398	
399	  var keyMap = { '.': 'dot', ',': 'dot', '+': 'add', '-': 'sub', '*': 'mul', 'x': 'mul',
400	    '/': 'div', '(': 'lparen', ')': 'rparen', '=': 'equals', 'Enter': 'equals', 'Escape': 'clear', 'c': 'clear', 'C': 'clear' };
401	  document.addEventListener('keydown', function (e) {
402	    if (e.metaKey || e.ctrlKey || e.altKey) return;
403	    var key = /^[0-9]$/.test(e.key) ? e.key : keyMap[e.key];
404	    if (key) {
405	      e.preventDefault();
406	      press(key);
407	    }
408	  });
409	
410	  reset();
411	  render();
412	})();
413	</script>
414	</body>
415	</html>
416

