S=/private/tmp/claude-501/-Users-vmysla-src-ab-study-arms-calculator-rep-v2-01-treatment-v2/71d1c4a8-6ccc-452c-b7df-f301b7f6e6ee/scratchpad && cat > $S/t.js <<'EOF'
<script>
(function(){
var out=[];
function q(t){return document.querySelector('[data-testid="'+t+'"]');}
function clk(seq){seq.split(' ').forEach(function(k){var b=q('key-'+k); if(!b){out.push('MISSING '+k);return;} b.click();});}
function kb(keys){keys.forEach(function(k){document.dispatchEvent(new KeyboardEvent('keydown',{key:k,bubbles:true}));});}
function d(){return q('calc-display').textContent;}
function t(name,exp){var got=d(); out.push((got===exp?'PASS ':'FAIL ')+name+' got='+got+' exp='+exp);}
function ac(){clk('clear');}
ac(); clk('2 add 3 mul 4 equals'); t('left-to-right',"20");
ac(); clk('1 div 0 equals'); t('div0','Error'); clk('5'); t('error ignores','Error'); ac(); t('ac','0');
ac(); clk('1 div 3 equals'); t('format','0.3333333333');
ac(); clk('0 dot 1 add 0 dot 2 equals'); t('float','0.3');
ac(); clk('5 sign'); t('sign','-5');
ac(); clk('2 mul lparen 3 add 4 rparen equals'); t('groups','14');
out.push('tape top: '+q('calc-tape').firstChild.textContent);
ac(); clk('7 mplus clear mr'); t('memory',"7"); out.push('mem active '+q('mem-indicator').getAttribute('data-active')); clk('mc');
out.push('percent key present: '+!!q('key-pct'));
